SELECT
heightId, mno, childId, height,
recordDate, created_at AS createdAt
FROM height_record
WHERE mno = #{mno}
AND childId = #{childId}


    AND recordDate >= #{startDate}


    AND recordDate <= #{endDate}


ORDER BY recordDate DESC

SELECT
heightId, mno, childId, height,
recordDate, created_at AS createdAt
FROM height_record
WHERE mno = #{mno}
AND childId IS NULL


    AND recordDate >= #{startDate}


    AND recordDate <= #{endDate}


ORDER BY recordDate DESC

